#!/usr/bin/env python3
"""Shipment summary builder.  Usage: summarize.py DATA_DIR OUT_FILE

Follows /app/docs (summary-format.md, corrections.md, handovers.md,
exports.md and the depot notes).  Python standard library only.
"""
import codecs
import csv
import datetime as dt
import gzip
import io
import json
import math
import os
import re
import sys
import xml.etree.ElementTree as ET
from decimal import Decimal
from fractions import Fraction

# ----------------------------------------------------------------- constants

KG = {
    "kg": Fraction(1),
    "g": Fraction(1, 1000),
    "lb": Fraction("0.45359237"),
    "oz": Fraction("0.028349523125"),
}
UNIT_ALIASES = {
    "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg",
    "g": "g", "gr": "g", "gram": "g", "grams": "g",
    "lb": "lb", "lbs": "lb", "pound": "lb", "pounds": "lb",
    "oz": "oz", "ounce": "oz", "ounces": "oz",
}

PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor",
            "lakeside"]

MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct",
     "nov", "dec"])}

NEW, CORR, VOID = "new", "corr", "void"

# Delimited-text depots: delimiter, quoting, column names, weight column,
# decimal-comma flag, base date form, base weight unit.
TEXT_DEPOTS = {
    "east": dict(delim=",", quoted=True,
                 cols=["id", "type", "shipped", "gross", "net", "status",
                       "note"],
                 id="id", type="type", date="shipped", weight="gross",
                 status="status", comma_decimal=False, date_form="YMD"),
    "lakeside": dict(delim=",", quoted=True,
                     cols=["id", "kind", "booked", "shipped", "gross_kg",
                           "net_kg", "status"],
                     id="id", type="kind", date="shipped", weight="gross_kg",
                     status="status", comma_decimal=False, date_form="iso",
                     field_unit="kg"),
    "harbor": dict(delim="|", quoted=False,
                   cols=["rec", "ref", "date", "weight", "state"],
                   id="ref", type="rec", date="date", weight="weight",
                   status="state", comma_decimal=False, date_form="iso"),
    "river": dict(delim="\t", quoted=False,
                  cols=["t", "ref", "shipped", "weight", "status"],
                  id="ref", type="t", date="shipped", weight="weight",
                  status="status", comma_decimal=False,
                  date_form="MM/DD/YYYY"),
    "west": dict(delim=";", quoted=False,
                 cols=["id", "typ", "shipped", "weight", "status", "note"],
                 id="id", type="typ", date="shipped", weight="weight",
                 status="status", comma_decimal=True,
                 date_form="DD.MM.YYYY"),
}

HARBOR_STATES = {"DLV": "delivered", "DLL": "delivered_late",
                 "CAN": "cancelled", "RET": "returned", "HLD": "held"}
SOUTH_STATES = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
                "R": "returned", "H": "held"}

# Fixed-width layouts: record length and (start, end) 1-based inclusive.
LAYOUTS = {
    "FW1": dict(length=42, id=(1, 9), type=(10, 10), shipped=(11, 17),
                weight=(18, 25), status=(26, 26), dfmt="YYYYDDD",
                wunit="g", wscale=Fraction(1)),
    "FW2": dict(length=43, type=(1, 1), id=(2, 10), shipped=(11, 18),
                weight=(19, 26), status=(27, 27), dfmt="YYYYMMDD",
                wunit="kg", wscale=Fraction(1, 100)),
    "FW3": dict(length=41, id=(1, 9), shipped=(10, 16), type=(17, 17),
                weight=(18, 24), status=(25, 25), dfmt="YYYYDDD",
                wunit="lb", wscale=Fraction(1, 10)),
}

# ------------------------------------------------------------- byte/text io


def read_text(path):
    with open(path, "rb") as fh:
        data = fh.read()
    while data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return decode_bytes(data)


def decode_bytes(data):
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8", errors="replace")
    if data[:2] == b"\xff\xfe":
        return data[2:].decode("utf-16-le", errors="replace")
    if data[:2] == b"\xfe\xff":
        return data[2:].decode("utf-16-be", errors="replace")
    enc = "utf-8"
    head = data[:2048].decode("latin-1")
    for line in head.split("\n")[:30]:
        m = re.match(r"\s*#\s*charset\s*:\s*([^\s]+)", line, re.I)
        if m:
            try:
                enc = codecs.lookup(m.group(1).strip()).name
            except LookupError:
                enc = "utf-8"
            break
    return data.decode(enc, errors="replace")


def split_lines(text):
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    return [l[:-1] if l.endswith("\r") else l for l in lines]


# ----------------------------------------------------------------- values


def norm_id(raw):
    """Return the shipment number (int) or None."""
    if raw is None:
        return None
    m = re.match(r"^\s*SH\D*?(\d+)\s*$", raw, re.I)
    if not m:
        return None
    return int(m.group(1))


def norm_status(raw):
    s = (raw or "").strip().lower()
    s = re.sub(r"[\s\-]+", "_", s)
    return s


def counted(status):
    return status in ("delivered", "delivered_late")


def norm_unit(u):
    if u is None:
        return None
    return UNIT_ALIASES.get(u.strip().lower().rstrip("."))


def parse_number(s, comma_decimal):
    s = s.strip().replace(" ", "").replace("\u00a0", "")
    if comma_decimal:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Fraction(s)


def parse_weight(raw, comma_decimal):
    """Return (Fraction value or None, unit or None)."""
    if raw is None:
        return None, None
    raw = raw.strip()
    if not raw:
        return None, None
    m = re.match(r"^([+-]?[0-9][0-9.,\s]*|[+-]?[.,][0-9]+)\s*([A-Za-z]+)?$",
                 raw)
    if not m:
        return None, None
    try:
        val = parse_number(m.group(1), comma_decimal)
    except (ValueError, ZeroDivisionError):
        return None, None
    return val, norm_unit(m.group(2))


def to_kg(val, unit):
    return val * KG[unit]


def norm_form(form):
    if not form:
        return None
    f = form.strip().upper()
    f = re.sub(r"\s*\(.*\)$", "", f)
    return f


def _mk(y, m, d):
    return dt.date(int(y), int(m), int(d))


def parse_date(raw, form):
    """Return the UTC date of a ship date / ship time, or None."""
    if raw is None:
        return None
    s = raw.strip()
    if not s:
        return None
    form = norm_form(form) or ""
    offset = dt.timedelta(0)
    tod = None
    m = re.match(r"^(.+?)[T ]\s*(\d{1,2}:\d{2}(?::\d{2}(?:[.,]\d+)?)?)\s*"
                 r"(Z|z|UTC|[+-]\d{2}(?::?\d{2})?)?$", s)
    if m and not re.match(r"^\d+:\d+$", s):
        s = m.group(1).strip()
        tparts = m.group(2).replace(",", ".").split(":")
        h, mi = int(tparts[0]), int(tparts[1])
        sec = float(tparts[2]) if len(tparts) > 2 else 0.0
        tod = dt.timedelta(hours=h, minutes=mi, seconds=sec)
        z = m.group(3)
        if z and z[0] in "+-":
            zz = z[1:].replace(":", "")
            oh = int(zz[:2])
            om = int(zz[2:4]) if len(zz) > 2 else 0
            offset = dt.timedelta(hours=oh, minutes=om)
            if z[0] == "-":
                offset = -offset
    d = None
    m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})$", s)
    if m:
        d = _mk(*m.groups())
    if d is None:
        m = re.match(r"^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$", s)
        if m:
            a, b, y = m.groups()
            fi_d = form.find("D")
            fi_m = form.find("M")
            if fi_m != -1 and (fi_d == -1 or fi_m < fi_d):
                d = _mk(y, a, b)
            else:
                d = _mk(y, b, a)
    if d is None:
        m = re.match(r"^(\d{1,2})[ \-]([A-Za-z]{3,9})\.?,?[ \-](\d{4})$", s)
        if m and m.group(2)[:3].lower() in MONTHS:
            d = _mk(m.group(3), MONTHS[m.group(2)[:3].lower()], m.group(1))
    if d is None:
        m = re.match(r"^([A-Za-z]{3,9})\.? (\d{1,2}),? (\d{4})$", s)
        if m and m.group(1)[:3].lower() in MONTHS:
            d = _mk(m.group(3), MONTHS[m.group(1)[:3].lower()], m.group(2))
    if d is None and re.match(r"^\d+(\.\d+)?$", s):
        if form == "SERIAL":
            kind = "serial"
        elif re.match(r"^\d{8}$", s):
            kind = "ymd8"
        elif re.match(r"^\d{7}$", s):
            kind = "ydoy"
        else:
            kind = "serial"
        if kind == "ymd8":
            d = _mk(s[:4], s[4:6], s[6:8])
        elif kind == "ydoy":
            d = dt.date(int(s[:4]), 1, 1) + dt.timedelta(days=int(s[4:]) - 1)
        else:
            val = float(s)
            whole = math.floor(val)
            d = dt.date(1899, 12, 30) + dt.timedelta(days=whole)
            frac = val - whole
            if frac:
                tod = dt.timedelta(days=frac)
    if d is None:
        return None
    if tod is not None:
        full = dt.datetime.combine(d, dt.time()) + tod - offset
        return full.date()
    return d


# ------------------------------------------------------------- record model


class Rec:
    __slots__ = ("num", "type", "date", "kg", "status")

    def __init__(self, num, type_, date, kg, status):
        self.num = num
        self.type = type_
        self.date = date
        self.kg = kg
        self.status = status


def norm_type(raw):
    s = (raw or "").strip().upper()
    if s in ("C", "COR", "CORR", "CORRECTION", "AMEND", "AMENDMENT"):
        return CORR
    if s in ("V", "VOID"):
        return VOID
    return NEW


DIRECTIVE_RE = re.compile(r"^#\s*([A-Za-z][A-Za-z _\-]*?)\s*:\s*(.*?)\s*$")


def norm_dname(name):
    return re.sub(r"[\s_\-]+", " ", name.strip().lower())


# ------------------------------------------------------------ text parsing


def logical_rows(lines):
    """Yield ('comment', line) or ('row', text) with quoted fields joined."""
    i, n = 0, len(lines)
    while i < n:
        line = lines[i]
        i += 1
        if line.startswith("#"):
            yield "comment", line
            continue
        if not line.strip():
            continue
        yield "row", line


def parse_text_export(depot, cfg, text):
    lines = split_lines(text)
    seq = None
    recs = []
    directives = {}
    header = None
    colset = set(cfg["cols"])
    pending = None
    i, n = 0, len(lines)
    while i < n:
        line = lines[i]
        i += 1
        if line.startswith("#"):
            m = DIRECTIVE_RE.match(line)
            if m:
                name = norm_dname(m.group(1))
                directives[name] = m.group(2)
                if name == "seq" and seq is None:
                    mm = re.match(r"\s*(\d+)", m.group(2))
                    if mm:
                        seq = int(mm.group(1))
            else:
                mm = re.search(r"\bseq\s*=\s*(\d+)", line)
                if mm and seq is None:
                    seq = int(mm.group(1))
            continue
        if not line.strip():
            continue
        if cfg["quoted"]:
            while line.count('"') % 2 == 1 and i < n:
                line += "\n" + lines[i]
                i += 1
            try:
                fields = next(csv.reader([line], delimiter=cfg["delim"]))
            except (csv.Error, StopIteration):
                continue
        else:
            fields = line.split(cfg["delim"])
        low = [f.strip().lower() for f in fields]
        if low and all(f in colset for f in low) and len(set(low)) == len(low):
            header = low
            continue
        if header is None:
            header = list(cfg["cols"])
        first = fields[0].strip().upper() if fields else ""
        if first == "TOTAL":
            continue
        rowunit = None
        hdr = header
        if len(fields) == len(hdr) + 1:
            wcol = cfg["weight"]
            idx = hdr.index(wcol) + 1 if wcol in hdr else None
            if idx is not None and norm_unit(fields[idx]) and \
                    fields[idx].strip():
                rowunit = norm_unit(fields[idx])
                fields = fields[:idx] + fields[idx + 1:]
            else:
                for j, f in enumerate(fields):
                    if f.strip().lower() in UNIT_ALIASES:
                        rowunit = norm_unit(f)
                        fields = fields[:j] + fields[j + 1:]
                        break
        row = {}
        for j, h in enumerate(hdr):
            row[h] = fields[j] if j < len(fields) else ""
        num = norm_id(row.get(cfg["id"]))
        if num is None:
            continue
        rtype = norm_type(row.get(cfg["type"]))
        if rtype == VOID:
            recs.append(Rec(num, VOID, None, None, None))
            continue
        # date
        dform = directives.get("dates") or directives.get("date format") \
            or cfg["date_form"]
        date = parse_date(row.get(cfg["date"]), dform)
        # weight
        val, unit = parse_weight(row.get(cfg["weight"]), cfg["comma_decimal"])
        if unit is None and cfg.get("field_unit"):
            unit = cfg["field_unit"]
        if unit is None:
            unit = rowunit
        if unit is None:
            du = directives.get("unit") or directives.get("weight unit")
            if du:
                mm = re.match(r"\s*([A-Za-z]+)", du)
                unit = norm_unit(mm.group(1)) if mm else None
        if unit is None:
            unit = "kg"
        kg = to_kg(val, unit) if val is not None else Fraction(0)
        st = row.get(cfg["status"], "")
        if depot == "harbor":
            st = HARBOR_STATES.get(st.strip().upper(), st)
        recs.append(Rec(num, rtype, date, kg, norm_status(st)))
    return seq, recs


# ----------------------------------------------------------- fixed width


def parse_south(text):
    lines = split_lines(text)
    seq = None
    layout = None
    by_len = {v["length"]: k for k, v in LAYOUTS.items()}
    recs = []
    for line in lines:
        if line.startswith("#"):
            m = re.match(r"^#\s*LAYOUT\s+(\S+)", line, re.I)
            if m:
                layout = m.group(1).upper()
                continue
            m = re.match(r"^#\s*SEQ\s*[:=]?\s*(\d+)", line, re.I)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if "\x0c" in line or re.match(r"^\s*SOUTH DEPOT", line):
            continue
        if not line.strip():
            continue
        lay = None
        if layout in LAYOUTS and len(line) == LAYOUTS[layout]["length"]:
            lay = LAYOUTS[layout]
        elif len(line) in by_len:
            lay = LAYOUTS[by_len[len(line)]]
        elif layout in LAYOUTS:
            lay = LAYOUTS[layout]
            line = line.ljust(lay["length"])
        else:
            continue

        def f(name):
            a, b = lay[name]
            return line[a - 1:b]

        num = norm_id(f("id"))
        if num is None:
            continue
        rtype = norm_type(f("type"))
        if rtype == VOID:
            recs.append(Rec(num, VOID, None, None, None))
            continue
        date = parse_date(f("shipped"), lay["dfmt"])
        try:
            w = Fraction(int(f("weight").strip())) * lay["wscale"]
        except ValueError:
            w = Fraction(0)
        kg = to_kg(w, lay["wunit"])
        st = SOUTH_STATES.get(f("status").strip().upper(), f("status"))
        recs.append(Rec(num, rtype, date, kg, norm_status(st)))
    return seq, recs


# ------------------------------------------------------------------- xml


def parse_central(text):
    text = re.sub(r"^\s*<\?xml[^>]*\?>", "", text)
    root = ET.fromstring(text)
    seq = None
    try:
        seq = int(root.get("seq"))
    except (TypeError, ValueError):
        pass
    root_unit = norm_unit(root.get("weight-unit")) or "kg"
    recs = []
    for el in root.iter("shipment"):
        num = norm_id(el.get("id"))
        if num is None:
            c = el.find("id")
            num = norm_id(c.text if c is not None else None)
        if num is None:
            continue
        rtype = norm_type(el.get("type"))
        if rtype == VOID:
            recs.append(Rec(num, VOID, None, None, None))
            continue
        sh = el.get("shipped")
        c = el.find("shipped")
        if c is not None and c.text and c.text.strip():
            sh = c.text
        date = parse_date(sh, "DD Mon YYYY")
        w = el.find("weight")
        kg = Fraction(0)
        if w is not None:
            val, unit = parse_weight(w.text, False)
            unit = norm_unit(w.get("unit")) or unit or \
                norm_unit(el.get("weight-unit")) or root_unit
            if val is not None:
                kg = to_kg(val, unit)
        s = el.find("status")
        st = s.text if s is not None else el.get("status")
        recs.append(Rec(num, rtype, date, kg, norm_status(st)))
    return seq, recs


# ------------------------------------------------------------------ json


def parse_north(text):
    seq = None
    recs = []
    for line in split_lines(text):
        if not line.strip():
            continue
        try:
            obj = json.loads(line, parse_float=Decimal)
        except ValueError:
            continue
        items = obj if isinstance(obj, list) else [obj]
        for o in items:
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                if seq is None and o["meta"].get("seq") is not None:
                    try:
                        seq = int(o["meta"]["seq"])
                    except (TypeError, ValueError):
                        pass
                continue
            num = norm_id(str(o.get("id", "")))
            if num is None:
                continue
            rtype = norm_type(o.get("kind"))
            if rtype == VOID:
                recs.append(Rec(num, VOID, None, None, None))
                continue
            date = parse_date(o.get("shipped_at"), "iso")
            kg = Fraction(0)
            for k, v in o.items():
                kl = k.lower()
                if kl == "weight" or kl.startswith("weight_"):
                    unit = norm_unit(kl[7:]) if kl.startswith("weight_") \
                        else None
                    val, u2 = parse_weight(str(v), False)
                    unit = unit or u2 or norm_unit(str(o.get("unit", ""))) \
                        or "kg"
                    if val is not None:
                        kg = to_kg(val, unit)
                    break
            recs.append(Rec(num, rtype, date, kg,
                            norm_status(str(o.get("status", "")))))
    return seq, recs


# ------------------------------------------------------------------ main


def parse_file(depot, path):
    text = read_text(path)
    if depot == "central":
        return parse_central(text)
    if depot == "north":
        return parse_north(text)
    if depot == "south":
        return parse_south(text)
    if depot in TEXT_DEPOTS:
        return parse_text_export(depot, TEXT_DEPOTS[depot], text)
    # unknown depot: guess from content
    stripped = text.lstrip()
    if stripped.startswith("<"):
        return parse_central(text)
    if stripped.startswith("{") or stripped.startswith("["):
        return parse_north(text)
    return None, []


def money(frac):
    n = math.floor(frac * 100 + Fraction(1, 2))
    return float(Decimal(n).scaleb(-2))


def main(data_dir, out_file):
    files = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split("-")[0].lower()
        files.setdefault(depot, []).append((name, p))

    corrections = 0
    resends = 0
    current = {}  # depot -> {num: Rec}
    for depot, flist in files.items():
        parsed = []
        for name, p in flist:
            try:
                seq, recs = parse_file(depot, p)
            except Exception as exc:  # keep going on a damaged export
                sys.stderr.write("warning: %s: %s\n" % (name, exc))
                seq, recs = None, []
            parsed.append((seq if seq is not None else -1, name, recs))
        parsed.sort(key=lambda t: (t[0], t[1]))
        cur = {}
        for _, _, recs in parsed:
            for r in recs:
                if r.type == NEW:
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.type == CORR:
                    cur[r.num] = r
                    corrections += 1
                else:
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(PRIORITY)}
    owners = {}
    for depot, cur in current.items():
        for num in cur:
            owners.setdefault(num, []).append(depot)
    handovers = 0
    kept = {}
    for num, deps in owners.items():
        if len(deps) > 1:
            handovers += 1
        deps.sort(key=lambda d: (order.get(d, len(order)), d))
        kept[num] = (deps[0], current[deps[0]][num])

    dep_tot = {d: [0, Fraction(0)] for d in files}
    mon_tot = {}
    for num, (depot, r) in kept.items():
        if not counted(r.status) or r.date is None:
            continue
        dep_tot[depot][0] += 1
        dep_tot[depot][1] += r.kg
        key = "%04d-%02d" % (r.date.year, r.date.month)
        m = mon_tot.setdefault(key, [0, Fraction(0)])
        m[0] += 1
        m[1] += r.kg

    out = {
        "depots": {d: {"shipments": dep_tot[d][0],
                       "total_kg": money(dep_tot[d][1])}
                   for d in sorted(dep_tot)},
        "months": {k: {"shipments": mon_tot[k][0],
                       "total_kg": money(mon_tot[k][1])}
                   for k in sorted(mon_tot)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    os.makedirs(os.path.dirname(os.path.abspath(out_file)), exist_ok=True)
    with open(out_file, "w", encoding="utf-8") as fh:
        json.dump(out, fh, indent=2)
        fh.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.stderr.write("usage: summarize.py DATA_DIR OUT_FILE\n")
        sys.exit(2)
    main(sys.argv[1], sys.argv[2])

